fetch('knowledge/results/wep3/latest.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{const names={internal_credit_settled:'独立审计通过，内部积分结算完成',audit_rejected:'审计拒绝，未结算',settlement_blocked:'交付已审核，结算受阻',blocked:'执行受阻',live_contract_check_failed:'实时契约检查未通过（不能认定任务完成）'};document.getElementById('state').textContent=Object.hasOwn(names,d.status)?names[d.status]:(typeof d.status==='string'&&d.status?d.status:'状态未知');document.getElementById('money').textContent='回执付款标记（未独立链上核验）：'+(d.paid===true?'是':d.paid===false?'否':'未知')+'；交易哈希：'+(d.tx_hash||'无');document.getElementById('detail').textContent=JSON.stringify({time:d.at,execution_id:d.execution_id,source_commit:d.source_commit,trigger_commit:d.trigger_commit,source:d.source,task_status:d.status,worker_generation:d.worker_generation&&typeof d.worker_generation==='object'?Object.fromEntries(['status','actual_provider','model','finish_reason','tokens_used','request_id'].filter(k=>Object.hasOwn(d.worker_generation,k)&&['string','number','boolean'].includes(typeof d.worker_generation[k])).map(k=>[k,d.worker_generation[k]])):undefined,failed_checks:Array.isArray(d.live_checks)?d.live_checks.filter(x=>x?.passed===false).map(x=>({id:x.id,path:x.path,expected_http:x.comparison?.expected_http??x.expected_http,actual_http:x.comparison?.actual_http??x.http,http_matched:x.comparison?.http_matched,expected_shape_valid:x.comparison?.expected_shape_valid,failed_fields:Array.isArray(x.comparison?.fields)?x.comparison.fields.filter(f=>f?.matched===false).map(f=>({key:f.key,expected:f.expected,actual:f.actual,actual_present:f.actual_present})):[]})):undefined,audit:d.audit,reason:d.reason,receipt:d.result?.receipt},null,2)}).catch(()=>document.getElementById('state').textContent='暂无可读取回执，不能认定完成');
#300固定head=17912d13e30a304e75cdce9746293c5e8596b2fd treasury-dashboard.html sha256=b7309adc7ff91883035ec8960e6ca647476b3504907893e33851d3a862ed16cd。仅修改用量未知逻辑，以下为完整两个新函数及使用处，其他DOM字段已有escapeHtml；HTTP非2xx会抛错。请注意null/空/无效值显示未知，真实0保留，进度0..100。
function usagePercent(used, limit) {
  const numeric = value => typeof value === 'number' || (typeof value === 'string' && value.trim() !== '');
  if (!numeric(used) || !numeric(limit)) return null;
  const amount = Number(used), cap = Number(limit);
  if (!Number.isFinite(amount) || !Number.isFinite(cap) || amount < 0 || cap <= 0) return null;
  if (amount >= cap) return 100;
  return Math.min(100, Math.max(0, Math.round((amount / cap) * 100)));
}
function displayValue(value) {
  return value == null || (typeof value === 'string' && value.trim() === '') ? '未知' : value;
}
  const g = document.getElementById('agents');
  g.innerHTML = Object.entries(d.agents || {}).map(([name, u]) => {
    u = u ?? {};
    const pct = usagePercent(u.used, u.daily_limit);
    const bar = pct == null ? '<div class="muted">用量比例未知</div>' : '<div class="bar"><i style="width:'+pct+'%"></i></div>';
    return '<div class="card"><h3>'+escapeHtml(name)+'</h3><div>已用 <b>'+escapeHtml(displayValue(u.used))+'</b> / '+escapeHtml(displayValue(u.daily_limit))+
      '</div><div class="muted">单笔≤'+escapeHtml(displayValue(u.single_limit))+' · 剩 '+escapeHtml(displayValue(u.remaining))+
      '</div>'+bar+'</div>';
  }).join('');
